const today = $now.toFormat('yyyy-MM-dd');
const targetSlot = $('Edit Fields').first().json.slot;

const matched = $input.all().filter(item => 
  item.json.Tanggal === today && item.json.Slot === targetSlot
);

if (matched.length === 0) {
  throw new Error(`Tidak ada data untuk tanggal ${today} slot ${targetSlot}`);
}

return matched;

const original = $('Filter Tema Hari Ini').first().json;

return [{
  json: {
    tanggal: original.Tanggal,
    slot: original.Slot,
    pilar: original.Pilar,
    tema: original.Tema,
    format_visual: original['Format Visual'],
    jumlah_slide: original['Jumlah Slide'],
    sumber: 'default_kalender',
    arahan_tambahan: '',
    akun: original.Akun || '',
    mode_visual: original['Mode Visual'] || '',
    revisi: 'semua',
    caption_lama: '',
    gambar_lama: ''
  }
}];

const j = $json;
let o = {};
try { o = $('Filter Tema Hari Ini').first().json; } catch (e) {}
const pick = (...v) => v.find(x => x !== undefined && x !== null && String(x).trim() !== '');
const fmt = pick(j['Format Visual'], j.format_visual, o['Format Visual'], 'single');
const jml = Number(pick(j['Jumlah Slide'], j.jumlah_slide, o['Jumlah Slide'], 1)) || 1;
let revisi = pick(j.Revisi, 'semua');
const capLama = pick(j.CaptionLama, '') || '';
const gamLama = pick(j.GambarLama, '') || '';
if (revisi === 'visual' && !capLama) revisi = 'semua';
if (revisi === 'copy' && !gamLama) revisi = 'semua';
return [{ json: {
  tanggal: pick(j.Tanggal, j.tanggal, o.Tanggal, $now.toFormat('yyyy-MM-dd')),
  slot: pick(j.Slot, j.slot, o.Slot, $now.hour < 12 ? 'pagi' : 'sore'),
  pilar: pick(j.Pilar, j.pilar, o.Pilar, 'umum'),
  tema: pick(j.Tema, j.tema, o.Tema, ''),
  format_visual: fmt,
  jumlah_slide: jml,
  sumber: j.Timestamp ? 'override_telegram' : 'dipanggil_langsung',
  arahan_tambahan: pick(j.Instruksi, j.arahan, '') || '',
  gambar_url: pick(j.Gambar, j.gambar_url, '') || '',
  akun: pick(j.Akun, j.akun, o.Akun, '') || '',
  revisi, caption_lama: capLama, gambar_lama: gamLama
} }];

