const item = $input.first();

return [{
  json: {
    ...item.json,
    slide_number: 1
  },
  binary: item.binary
}];

let items;
try { items = $('Urutkan Slide').all(); } catch (e) { items = []; }
if (!items.length) items = $('Download Gambar Lama').all();
const maxSlots = 10;
const binaryData = {};
const mediaArray = [];

const caption = $('Caption Final').first().json.text;

for (let i = 0; i < maxSlots; i++) {
  const sourceIndex = i < items.length ? i : items.length - 1;
  binaryData[`slide${i}`] = items[sourceIndex].binary.data;
}

items.forEach((item, index) => {
  const mediaItem = { type: 'photo', media: `attach://slide${index}` };
  if (index === 0) {
    mediaItem.caption = caption;
  }
  mediaArray.push(mediaItem);
});

return [{
  json: {
    chatId: (() => { try { return $('Send a text message').first().json.result.chat.id; } catch (e) { return $('Dipanggil dari Handle Approval').first().json.chat_id; } })(),
    media: JSON.stringify(mediaArray)
  },
  binary: binaryData
}];

const all = $input.all().map(i => i.json);
const st = r => String(r.Status || '').trim().toLowerCase();
const news = all.filter(r => st(r) === 'new');
const wait = all.filter(r => st(r) === 'menunggu');
if (!news.length) return [{ json: { Status: 'none', plan_ts: wait.length ? wait[wait.length - 1].Timestamp : '' } }];
return [{ json: news[news.length - 1] }];

const base = $('Merge').first().json;
const profs = $('Ambil Profil').all().map(i => i.json).filter(r => r.Akun);
const want = String(base.akun || '').trim();
const p = profs.find(r => want && r.Akun === want) || profs.find(r => String(r.Aktif || '').toLowerCase() === 'ya') || profs[0] || {};
const rules = $input.all().map(i => i.json).filter(r => r.Aturan && (!r.Akun || r.Akun === p.Akun || r.Akun === '*')).map(r => '- ' + r.Aturan);
return [{ json: { ...base, profil: {
  akun: p.Akun || '', handle: p.Handle || '', nama: p['Nama Brand'] || '', audiens: p.Audiens || '',
  gaya_copy: p['Gaya Copy'] || '', gaya_visual: p['Gaya Visual'] || '',
  cta_cover: p['CTA Cover'] || '', cta_penutup: p['CTA Penutup'] || '',
  logo_id: p['Logo File ID'] || '', aturan: rules.join('\n')
} } }];

const slides = $('Gabungkan Semua Slide').all();
const first = $input.first();
const logo = first && first.binary && first.binary.data;
if (!logo) return slides;
return slides.map(it => ({ json: it.json, binary: { data: it.binary.data, logo } }));

