parameters.jsCode:
let t = String($input.first().json.output[0].content[0].text || '').trim();
t = t.replace(/^```(?:json)?/i, '').replace(/```$/, '').trim();
const obj = JSON.parse(t);
let slides = Array.isArray(obj) ? obj : (obj.slides || []);
const want = Number($('Merge').first().json.jumlah_slide) || slides.length;
const clean = (v) => typeof v === 'string' ? v.replace(/[—–]/g, ',') : Array.isArray(v) ? v.map(clean) : (v && typeof v === 'object') ? Object.fromEntries(Object.entries(v).map(([k, x]) => [k, clean(x)])) : v;
slides = slides.slice(0, want).map(clean);
if (slides.length) { slides[0].layout = 'hook'; if (slides.length > 1) slides[slides.length - 1].layout = 'cta'; }
if (slides.length > 1) { slides[slides.length - 1].cta_title = ''; }
slides.forEach((x) => { if (x.layout === 'hook' && x.subtitle) x.subtitle = String(x.subtitle).replace(/\s*geser[^.!?]*[.!?]?/ig, '').trim(); });
const total = slides.length;
return slides.map((s, i) => ({ json: { slide_number: i + 1, total_slides: total, n: i + 1, total, slide: s } }));

const src = $('Parse Slide Kartu').all();
return $input.all().map((it, i) => {
  const b = it.binary && it.binary.data ? it.binary.data : null;
  if (b) { b.fileName = 'slide-' + src[i].json.slide_number + '.png'; b.mimeType = 'image/png'; }
  return { json: { ...src[i].json }, binary: it.binary };
});
